import java.util.*;

public class Main {
    ListNode detectCycle(ListNode head) {
        Set<ListNode> visited = new HashSet<>();
        ListNode node = head;
        while (node != null) {
            if (visited.contains(node)) {                                          // a node seen twice means this is where the cycle begins
                return node;
            }
            visited.add(node);
            node = node.next;
        }
        return null;                                                                // reached the end with no repeats: no cycle
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(3, new ListNode(2, new ListNode(0, new ListNode(-4))));
        head.next.next.next.next = head.next;
        ListNode result = solution.detectCycle(head);
        System.out.println(result != null ? result.val : "null");
    }
}

