#include <bits/stdc++.h>
using namespace std;

ListNode* detectCycle(ListNode* head) {
    unordered_set<ListNode*> visited;
    ListNode* node = head;
    while (node) {
        if (visited.count(node)) {                                               // a node seen twice means this is where the cycle begins
            return node;
        }
        visited.insert(node);
        node = node->next;
    }
    return nullptr;                                                               // reached the end with no repeats: no cycle
}

int main() {
    ListNode* head = new ListNode(3, new ListNode(2, new ListNode(0, new ListNode(-4))));
    head->next->next->next->next = head->next;
    ListNode* result = detectCycle(head);
    cout << (result ? to_string(result->val) : "null") << endl;
    return 0;
}

