import java.util.*;

public class Main {
    ListNode detectCycle(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) {                                                    // slow and fast met: a cycle exists somewhere
                ListNode ptr = head;
                while (ptr != slow) {                                                // both now move at the SAME speed (1 step)
                    ptr = ptr.next;
                    slow = slow.next;
                }
                return ptr;                                                           // they must meet exactly at the cycle's start
            }
        }
        return null;                                                                    // fast reached the end: no cycle
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(3, new ListNode(2, new ListNode(0, new ListNode(-4))));
        head.next.next.next.next = head.next;
        ListNode result = solution.detectCycle(head);
        System.out.println(result != null ? result.val : "null");
    }
}

